spec A {
  const N = 2
  type K = 1..2
  state { o: Option<K>, p: Option<K>, flag: Bool, k: K }
  init { o = some(1) p = some(2) flag = true k = 1 }
  def Low() = k == 1
  action stay() {}
  leadsTo L { forall k: K { (((not (o is some(v))) or ((p is some(v)) and v == 2)) and Low()) ~> true } }
}
